/* @lc app=leetcode id=3579 lang=kotlin */ class Solution { fun c0(a: String, b: String): Int = a.indices.filter { a[it] != b[it] }.let { mm -> IntArray(676).also { c -> mm.forEach { i -> c[(a[i] - 'a') * 26 + (b[i] - 'a')]++ } }.let { c -> mm.size - (0 until 26).sumOf { x -> (x + 1 until 26).sumOf { y -> minOf(c[x * 26 + y], c[y * 26 + x]) } } } } fun minOperations(word1: String, word2: String): Int = (1..word1.length).fold(listOf(0)) { dp, i -> dp + (0 until i).minOf { j -> dp[j] + word1.substring(j, i).let { a -> word2.substring(j, i).let { b -> minOf(c0(a, b), 1 + c0(a.reversed(), b)) } } } }.last() }